\title{Prime-Base Binomial Congruences:\\ The Prime Fibre and the Composite Frontier}
\author{Aristotle}
\date{2026-07-03}

\begin{document}
\maketitle

\begin{abstract}
Fix an integer base $q \ge 2$. We study the natural numbers $n$ satisfying the
\emph{prime-base binomial congruence}
\[
  \binom{qn}{n} \equiv q^{n} \pmod{n}.
\]
Our first main result is that this congruence holds for \emph{every prime}
$n = p$ and \emph{every base} $q$: both sides reduce to $q$ modulo $p$, the left
by Lucas' theorem and the right by Fermat's little theorem. Consequently the
solution set is infinite for every base, unconditionally. Our second
contribution concerns the composite family $n = q^{t} p$, whose existence is
governed by the integer
\[
  A_t = \binom{q^{\,t+1}}{q^{\,t}} - q^{\,q^{t}}.
\]
We prove that the central prime-power binomial coefficient
$\binom{q^{t+1}}{q^{t}}$ carries exactly one factor of $q$ (one carry in base-$q$
addition, via Kummer/Legendre), and deduce that $q$ divides $A_t$ exactly once
for all $t \ge 1$: $q \mid A_t$ but $q^2 \nmid A_t$. This isolates the base $q$
to a single factor of $A_t$, so the base can never serve as the auxiliary prime
$p$ in $n = q^t p$; the ``$p \neq q$'' condition of the composite conjecture is
therefore automatic. We situate these results against the open conjecture that
infinitely many composite solutions of shape $n = q^t p$ exist, and describe the
arithmetic of the residual $R_t = A_t / q$ as the remaining obstruction.
\end{abstract}

\noindent\textbf{Keywords:} binomial coefficients, Lucas' theorem, Kummer's
theorem, Fermat's little theorem, $q$-adic valuation, digit sums, prime
divisors, congruences.

\section{Introduction}

Binomial coefficients modulo integers have been a rich source of arithmetic
phenomena since the classical work of Lucas and Kummer. A recurring theme is to
compare a binomial coefficient with a simpler arithmetic quantity and ask when
they are congruent modulo a modulus depending on the parameters.

We fix a base $q \ge 2$ and consider the comparison
\begin{equation}
  \binom{qn}{n} \quad \text{versus} \quad q^{n} \pmod{n}.
  \label{eq:main}
\end{equation}
The left-hand side generalizes the central binomial coefficient (recovered at
$q = 2$); the right-hand side is the pure $n$-th power of the base. There is no a
priori reason for these to agree modulo $n$, and for generic $n$ they do not.
Nevertheless the congruence holds along the full sequence of primes for every
base, and we analyze the arithmetic controlling a sparser composite family.

\begin{definition}[Prime-base binomial congruence]
For integers $q \ge 2$ and $n \ge 1$ we say $n$ is a \emph{solution for base $q$}
if $\binom{qn}{n} \equiv q^{n} \pmod{n}$.
\end{definition}

\begin{definition}[Base-$q$ digit sum]
For $q \ge 2$ and $n \ge 0$, let $s_q(n)$ denote the sum of the base-$q$ digits
of $n$: if $n = \sum_i d_i q^i$ with $0 \le d_i < q$, then $s_q(n) = \sum_i d_i$.
\end{definition}

\paragraph{Overview.} Theorem~A (prime fibre) is proved in Section~\ref{sec:prime};
Theorem~B (central valuation) in Section~\ref{sec:central}; Theorem~C (exact
valuation of $A_t$) in Section~\ref{sec:At}. Section~\ref{sec:composite} discusses
the composite family; Section~\ref{sec:algo} gives algorithms and data; and
Section~\ref{sec:future} lists open problems.

\section{The prime fibre: every prime solves the congruence}
\label{sec:prime}

\begin{theorem}[Lucas]
Let $p$ be prime and write $m = \sum_i m_i p^i$, $k = \sum_i k_i p^i$ in base $p$
with $0 \le m_i, k_i < p$. Then
\[
  \binom{m}{k} \equiv \prod_i \binom{m_i}{k_i} \pmod{p}.
\]
Equivalently $\binom{m}{k} \equiv \binom{m \bmod p}{k \bmod p}
\binom{\lfloor m/p\rfloor}{\lfloor k/p\rfloor} \pmod p$.
\end{theorem}

\begin{lemma}[Lucas fibre]
\label{lem:lucas}
For every base $q$ and every prime $p$, $\binom{qp}{p} \equiv q \pmod{p}$.
\end{lemma}

\begin{proof}
Apply the recursive Lucas form to $m = qp$, $k = p$. The lowest digits are
$qp \bmod p = 0$ and $p \bmod p = 0$; the higher parts are $\lfloor qp/p\rfloor
= q$ and $\lfloor p/p \rfloor = 1$. Hence
\[
  \binom{qp}{p} \equiv \binom{0}{0}\binom{q}{1} = 1 \cdot q = q \pmod{p}.
\]
No relation between $q$ and $p$ is needed: the digit reduction $qp \mapsto (q,0)$
and $p \mapsto (1,0)$ holds for every base.
\end{proof}

\begin{theorem}[Fermat]
For every prime $p$ and every integer $a$, $a^{p} \equiv a \pmod{p}$.
\end{theorem}

\begin{lemma}[Fermat fibre]
\label{lem:fermat}
For every base $q$ and every prime $p$, $q^{p} \equiv q \pmod{p}$.
\end{lemma}

\begin{theorem}[Prime fibre; Theorem A]
\label{thm:A}
For every base $q$ and every prime $p$,
$\binom{qp}{p} \equiv q^{p} \pmod{p}$. Consequently the set
$\{\, n : \binom{qn}{n} \equiv q^{n} \pmod n \,\}$ is infinite for every base $q$.
\end{theorem}

\begin{proof}
By Lemma~\ref{lem:lucas}, $\binom{qp}{p} \equiv q \pmod p$; by
Lemma~\ref{lem:fermat}, $q^{p} \equiv q \pmod p$. Transitivity gives
$\binom{qp}{p} \equiv q^{p} \pmod p$, so $p$ is a solution. As there are
infinitely many primes, the solution set is infinite.
\end{proof}

\begin{remark}
Theorem~\ref{thm:A} makes ``infinitely many solutions'' \emph{unconditional} and
\emph{uniform in the base}. The nontrivial content lies in the solutions that are
not prime --- the composite family below.
\end{remark}

\section{The valuation of the central prime-power binomial coefficient}
\label{sec:central}

\begin{theorem}[Kummer]
Let $q$ be prime and $a, b \ge 0$. The exponent $\vq\!\big(\binom{a+b}{a}\big)$
equals the number of carries when adding $a$ and $b$ in base $q$.
\end{theorem}

An equivalent packaging via Legendre's formula $\vq(N!) = (N - s_q(N))/(q-1)$:
for $0 < k < q^{m}$,
\begin{equation}
  \vq\!\left(\binom{q^{m}}{k}\right) + \vq(k) = m.
  \label{eq:add}
\end{equation}

\begin{theorem}[Central valuation; Theorem B]
\label{thm:B}
For every prime $q$ and every $t \ge 0$,
$\vq\!\left(\binom{q^{\,t+1}}{q^{\,t}}\right) = 1$.
\end{theorem}

\begin{proof}
\emph{Via \eqref{eq:add}:} take $m = t+1$, $k = q^{t}$ (so $0 < q^t < q^{t+1}$).
Then $\vq(k) = t$, and \eqref{eq:add} gives
$\vq\big(\binom{q^{t+1}}{q^{t}}\big) = (t+1) - t = 1$.

\emph{Via Kummer:} write $\binom{q^{t+1}}{q^{t}} = \binom{a+b}{a}$ with
$a = q^{t}$, $b = (q-1)q^{t}$. In base $q$, $a$ is the digit $1$ and $b$ the
digit $q-1$, both in position $t$. Their sum $1+(q-1) = q$ overflows, producing
exactly one carry into position $t+1$; no other carries occur. Hence the
valuation is $1$.
\end{proof}

\begin{corollary}
\label{cor:C}
$q \mid \binom{q^{t+1}}{q^{t}}$ but $q^{2} \nmid \binom{q^{t+1}}{q^{t}}$, for
every prime $q$ and $t \ge 0$.
\end{corollary}

\section{Exact $q$-adic valuation of $A_t$}
\label{sec:At}

\begin{definition}
For $q \ge 2$ and $t \ge 0$ set
$A_t = \binom{q^{\,t+1}}{q^{\,t}} - q^{\,q^{t}} \in \Z$.
\end{definition}

\begin{theorem}[Exact valuation of $A_t$; Theorem C]
\label{thm:At}
For every prime base $q$ and every $t \ge 1$,
$q \mid A_t$ and $q^{2} \nmid A_t$; equivalently $\vq(A_t) = 1$.
\end{theorem}

\begin{proof}
Write $A_t = C - P$ with $C = \binom{q^{t+1}}{q^{t}}$ and $P = q^{q^{t}}$.

\emph{Divisibility by $q$.} By Corollary~\ref{cor:C}, $q \mid C$. Since $t \ge 1$,
$q^{t} \ge 1$, so $q \mid P$. Hence $q \mid (C - P) = A_t$.

\emph{Non-divisibility by $q^{2}$.} Since $t \ge 1$ and $q \ge 2$, we have
$q^{t} \ge 2$, so $q^{2} \mid P$. By Corollary~\ref{cor:C}, $q^{2} \nmid C$. If
$q^{2} \mid A_t$, then $C = A_t + P$ would be divisible by $q^{2}$, a
contradiction. Hence $q^{2} \nmid A_t$.
\end{proof}

