"""Base sweep: for several bases q, confirm every prime is a solution and
tabulate the small composite solutions that also appear."""
from __future__ import annotations
from math import comb
from typing import List


def is_prime(n: int) -> bool:
    if n < 2:
        return False
    i = 2
    while i * i <= n:
        if n % i == 0:
            return False
        i += 1
    return True


def congruent(q: int, n: int) -> bool:
    if n == 1:
        return True
    return comb(q * n, n) % n == pow(q, n, n)


def sweep(q: int, limit: int) -> List[int]:
    sols = [n for n in range(2, limit) if congruent(q, n)]
    primes = [p for p in range(2, limit) if is_prime(p)]
    assert all(p in sols for p in primes), "a prime failed to be a solution!"
    return sols


def main() -> None:
    for q in range(2, 7):
        sols = sweep(q, 60)
        comps = [n for n in sols if not is_prime(n)]
        print(f"base q={q}: all primes < 60 solve; extra composites = {comps}")


if __name__ == "__main__":
    main()

